symbols.collectorSource:
$ErrorActionPreference='Stop';$repo='E:/Programs/MPMY-src';$dest="$repo/_bin/aac-thread-origin-modules";New-Item -ItemType Directory -Path $dest -ErrorAction Stop | Out-Null
$rows=@();foreach($name in @('ntdll.dll','combase.dll')){
 $source=Join-Path "$env:SystemRoot/System32" $name
 Copy-Item -LiteralPath $source -Destination (Join-Path $dest $name)
 $rows+=@{name=$name;source=$source;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $source).Hash.ToLower();version=(Get-Item -LiteralPath $source).VersionInfo.FileVersion}
}
$rows | ConvertTo-Json | Set-Content "$dest/modules.json"
